/* Local product workflows. No external publication or inference. */
let audit=readLocal('ht-audit',[]),role=localStorage.getItem('ht-role')||'manager',composer=null,composerPreview='instagram',composerStep=0;let insightRange='week',mobileDetail=false;
let members=readLocal('ht-members',[{name:'مدیر فضای کار',role:'manager'},{name:'نویسنده محتوا',role:'writer'},{name:'بازبین تیم',role:'reviewer'}]);const roleNames={manager:'مدیر',writer:'نویسنده',reviewer:'بازبین'};let channelState=readLocal('ht-channel-state',{});let setupDone=readLocal('ht-setup',[]);const capability={instagram:'تصویر، ریلز و استوری',telegram:'متن و تصویر کانال',whatsapp:'پیش‌نویس پیام کسب‌وکار',linkedin:'متن و تصویر حرفه‌ای',youtube:'برنامه‌ریزی عنوان و توضیح ویدیو',facebook:'متن و تصویر صفحه'};
function logAction(text){audit.unshift({text,time:new Date().toISOString(),role});audit=audit.slice(0,80);localStorage.setItem('ht-audit',JSON.stringify(audit))}
function persistAccounts(){localStorage.setItem('ht-accounts',JSON.stringify(accounts));localStorage.setItem('ht-channel-state',JSON.stringify(channelState))}
function statusName(p){return {draft:'پیش‌نویس',review:'در انتظار تأیید',approved:'تأییدشده',scheduled:'برنامه‌ریزی‌شده'}[p.workflow]||(p.draft?'پیش‌نویس':'آماده بازبینی')}
function networkList(p){return p.networks?.length?p.networks:[p.network||'instagram']}
function mediaMarkup(p,i){return p.media&&/^data:image\/(png|jpeg|webp);base64,/.test(p.media)?`<div class="uploaded-media"><img src="${p.media}" alt="تصویر محتوای ${safe(p.title||'جدید')}"></div>`:miniArt(i)}
function openComposer(index=-1,seed={}){const p=index>=0?posts[index]:{title:'',caption:'',kind:'پست تصویری',networks:[],draft:true};composer={...structuredClone(p),...seed,index,networks:seed.networks||networkList(p),captions:{...(p.captions||{})},workflow:p.workflow||'draft',media:p.media||''};if(!composer.caption)composer.caption=seed.caption||'';composerPreview=composer.networks[0]||'instagram';composerStep=0;dialog.classList.add('composer-dialog');showComposer();dialog.showModal()}
function composerNetworks(){return [...new Set(accounts.map(a=>a.network))]}
function showComposer(){const available=composerNetworks();document.querySelector('#dialog-content').innerHTML=`<div class="composer-header"><div><small>استودیو هشتیوا</small><h2>${composer.index>=0?'بازبینی و ویرایش محتوا':'محتوای جدید'}</h2></div><span class="tag neutral">${roleNames[role]} · نسخه نمایشی</span></div><div class="composer-steps">${['آماده‌سازی','بازبینی شبکه‌ها','تأیید و زمان‌بندی'].map((s,i)=>`<button type="button" data-composer-step="${i}" class="${composerStep===i?'active':''}"><span>${fa(i+1)}</span>${s}</button>`).join('')}</div><div class="composer-layout"><div class="composer-fields">${composer.origin?`<div class="composer-origin">${icon('spark')} مبنای پیش‌نویس: ${safe(composer.origin)}</div>`:''}${composerStep===0?`<label for="content-title">عنوان داخلی محتوا</label><input id="content-title" data-cfield="title" value="${safe(composer.title)}" maxlength="100" placeholder="مثلاً راهنمای انتخاب هدیه"><label>شبکه‌های مقصد</label><div class="composer-networks">${available.map(n=>`<label class="network-check"><input type="checkbox" data-cnetwork="${n}" ${composer.networks.includes(n)?'checked':''}>${social(n)}<span>${socialNames[n]}</span></label>`).join('')||'<small>ابتدا یک حساب نمونه در بخش حساب‌ها اضافه کنید.</small>'}</div><label for="content-type">نوع محتوا</label><select id="content-type" data-cfield="kind">${['پست تصویری','متن','استوری','ریلز'].map(k=>`<option ${composer.kind===k?'selected':''}>${k}</option>`).join('')}</select><label for="content-caption">متن اصلی محتوا</label><textarea id="content-caption" data-cfield="caption" placeholder="پیام برند شما چیست؟">${safe(composer.caption)}</textarea><div class="caption-tools"><button type="button" class="text-link" data-caption-suggestion>${icon('spark')} پیشنهاد متن آماده</button><small id="caption-count">${fa(composer.caption.length)} نویسه</small></div><label class="media-drop">${icon('camera')}<b>${composer.media?'تغییر تصویر محتوا':'افزودن تصویر محتوا'}</b><small>PNG، JPG یا WebP · حداکثر ۱ مگابایت</small><input type="file" accept="image/png,image/jpeg,image/webp" id="composer-image"></label>${composer.media?'<button class="text-link" data-remove-media>حذف تصویر</button>':''}<small class="field-help">برای ویدیو، این نسخه فقط متن و برنامه را نگه می‌دارد؛ فایل ویدیویی بارگذاری نمی‌شود.</small>`:composerStep===1?`<h3>متن متناسب با هر شبکه</h3><p class="muted">تغییرات این مرحله فقط روی شبکه انتخاب‌شده اثر دارد.</p><div class="preview-network-tabs">${composer.networks.map(n=>`<button class="${composerPreview===n?'active':''}" data-preview-network="${n}">${social(n)}${socialNames[n]}</button>`).join('')}</div><label>متن ${socialNames[composerPreview]}</label><textarea data-variant="${composerPreview}">${safe(composer.captions[composerPreview]??composer.caption)}</textarea><div class="review-tip">${icon('spark')}<p>${{instagram:'شروع کوتاه، توضیح روشن و یک دعوت به تعامل داشته باشید.',telegram:'متن را به بندهای کوتاه تقسیم کنید و لینک موردنیاز را واضح قرار دهید.',whatsapp:'پیام را کوتاه، کاربردی و متناسب با مخاطب نگه دارید.',linkedin:'روی تجربه حرفه‌ای و یک نکته قابل استفاده تمرکز کنید.',youtube:'عنوان واضح و توضیح مرتبط با محتوای ویدیو بنویسید.',facebook:'متن کوتاه را با سؤال مشخص برای شروع گفتگو همراه کنید.'}[composerPreview]}</p></div><div class="review-checklist"><b>بازبینی پیش از تأیید</b><span>${icon(composer.media?'check':'camera')} تصویر: ${composer.media?'افزوده شده':'افزوده نشده'}</span><span>${icon('flow')} ${fa(composer.networks.length)} شبکه مقصد</span><span>${icon('users')} تأیید نهایی با مدیر یا بازبین</span></div>`:`<h3>تأیید و زمان‌بندی</h3><div class="review-checklist"><span>${icon('camera')} ${safe(composer.title||'بدون عنوان')}</span><span>${icon('flow')} ${composer.networks.map(n=>socialNames[n]).join('، ')}</span><span>${icon('users')} نقش فعلی: ${roleNames[role]}</span></div><label for="publish-at">تاریخ و ساعت پیشنهادی</label><input id="publish-at" data-cfield="due" type="datetime-local" value="${safe(composer.due||'')}"><small class="field-help" id="jalali-preview">${composer.due?new Intl.DateTimeFormat('fa-IR',{dateStyle:'full',timeStyle:'short'}).format(new Date(composer.due)):'تاریخ پس از انتخاب، به شمسی نمایش داده می‌شود.'}</small><label for="review-note">یادداشت برای بازبین</label><textarea id="review-note" data-cfield="reviewNote" placeholder="نکته‌ای برای بازبینی محتوا…">${safe(composer.reviewNote||'')}</textarea><div class="review-tip"><p>${role==='writer'?'شما می‌توانید محتوا را برای بازبینی ارسال کنید. تأیید و زمان‌بندی با مدیر یا بازبین است.':'پس از بررسی متن و رسانه، محتوا را تأیید یا برای زمان انتخاب‌شده در تقویم ثبت کنید.'}</p></div><small class="field-help">زمان‌بندی فقط در این پیش‌نمایش است؛ هیچ محتوایی به شبکه‌های اجتماعی ارسال نمی‌شود.</small>`}<div id="composer-error" role="alert"></div></div><div class="composer-preview-column"><div class="preview-label"><span>پیش‌نمایش محتوا</span><select id="preview-network-select" aria-label="شبکه پیش‌نمایش">${(composer.networks.length?composer.networks:['instagram']).map(n=>`<option value="${n}" ${composerPreview===n?'selected':''}>${socialNames[n]}</option>`).join('')}</select></div><div id="composer-preview"></div><small class="preview-disclaimer">پیش‌نمایش تقریبی؛ نمایش نهایی هر شبکه ممکن است متفاوت باشد.</small></div></div><div class="composer-footer"><button class="btn" data-save-composer="draft">ذخیره پیش‌نویس</button><div>${composerStep>0?button('مرحله قبل','data-composer-back'):''}${composerStep<2?button('ادامه بازبینی','data-composer-next',true,'arrow'):button('ارسال برای تأیید','data-save-composer="review"',role==='writer')}${composerStep===2&&role!=='writer'?button(composer.due?'تأیید و ثبت در تقویم':'تأیید محتوا','data-save-composer="approve"',true,'check'):''}</div></div>`;refreshComposerPreview()}
function refreshComposerPreview(){const n=composerPreview,text=composer.captions[n]??composer.caption;document.querySelector('#composer-preview').innerHTML=`<div class="social-preview ${n}"><div class="social-preview-head">${social(n)}<div><b>${safe(accounts.find(a=>a.network===n)?.name||'برند شما')}</b><small>${socialNames[n]}</small></div><span>•••</span></div>${composer.media?mediaMarkup(composer,0):'<div class="preview-placeholder">'+icon('camera')+'<span>تصویر محتوا</span></div>'}<div class="social-preview-caption">${safe(text||'متن محتوای شما اینجا نمایش داده می‌شود.')}</div>${n==='instagram'?`<div class="preview-reactions">${icon('heart')}${icon('inbox')}<span>ذخیره</span></div>`:''}</div>`}
function composerError(t){document.querySelector('#composer-error').textContent=t;return false}
function validateComposer(mode){if(!composer.title.trim())return composerError('عنوان محتوا را وارد کنید.');if(!composer.networks.length)return composerError('حداقل یک شبکه مقصد انتخاب کنید.');if(composer.networks.some(n=>!accounts.some(a=>a.network===n)))return composerError('برای شبکه مقصد ابتدا یک حساب نمونه اضافه کنید.');if(mode!=='draft'&&composer.networks.some(n=>!(composer.captions[n]??composer.caption).trim()))return composerError('متن یکی از شبکه‌های مقصد خالی است. آن را در بازبینی شبکه‌ها کامل کنید.');if(mode!=='draft'&&!composer.caption.trim())return composerError('برای بازبینی، متن اصلی محتوا را کامل کنید.');if(mode==='approve'){if(role==='writer')return composerError('نویسنده امکان تأیید نهایی ندارد.');if(composer.due&&new Date(composer.due)<=new Date())return composerError('زمان برنامه‌ریزی باید در آینده باشد.');if(composer.networks.some(n=>accounts.filter(a=>a.network===n).every(a=>channelState[a.id]==='disconnected')))return composerError('یکی از شبکه‌های مقصد فقط حساب قطع‌شده دارد. ابتدا وضعیت حساب را بررسی کنید.');if(composer.kind==='پست تصویری'&&!composer.media)return composerError('برای تأیید پست تصویری، یک تصویر اضافه کنید.');if(['ریلز','استوری'].includes(composer.kind))return composerError('ارسال رسانه این قالب در پیش‌نمایش پشتیبانی نمی‌شود؛ به صورت پیش‌نویس یا برای بازبینی ذخیره کنید.')}return true}
function saveComposer(mode){if(!validateComposer(mode))return;const status=mode==='approve'?(composer.due?'scheduled':'approved'):mode;const entry={...composer,workflow:status,draft:status==='draft',network:composer.networks[0],time:composer.due?new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(composer.due)):'بدون زمان',updatedAt:new Date().toISOString()};delete entry.index;const index=composer.index,previous=index>=0?posts[index]:null;if(index<0)posts.unshift(entry);else posts[index]=entry;try{localStorage.setItem('ht-posts',JSON.stringify(posts))}catch{if(index<0)posts.shift();else posts[index]=previous;return composerError('فضای ذخیره مرورگر کافی نیست. تصویر کوچک‌تری انتخاب کنید.')}logAction(`${statusName(entry)}: ${entry.title}`);dialog.close();dialog.classList.remove('composer-dialog');composer=null;location.hash='studio';render('studio');toast('محتوا در فضای نمایشی ذخیره شد')}
const modalBeforeProduct=modal;modal=function(html){dialog.classList.remove('composer-dialog');modalBeforeProduct(html)};
function studioV4(){const filtered=posts.map((p,i)=>({p,i})).filter(({p})=>postFilter==='all'||(postFilter==='draft'?p.draft:postFilter==='review'?p.workflow==='review':p.workflow==='scheduled'||p.workflow==='approved'));return titleV3('محتوا و انتشار','از ایده تا پیش‌نویس، تأیید تیم و تقویم انتشار.',button('محتوای جدید','data-action="post"',true,'plus'))+`<div class="section-toolbar"><div class="plain-tabs">${[['all','همه'],['draft','پیش‌نویس'],['review','نیازمند تأیید'],['ready','تأییدشده']].map(([v,t])=>`<button class="${postFilter===v?'chosen':''}" data-content-filter="${v}">${t}</button>`).join('')}</div><button class="btn" data-page="calendar">${icon('calendar')} تقویم</button></div><div class="publication-grid">${filtered.map(({p,i})=>`<article class="publication-card">${mediaMarkup(p,i)}<div class="publication-top"><div class="network-stack">${networkList(p).map(n=>social(n)).join('')}</div><span class="tag ${p.workflow==='review'?'amber':p.workflow==='scheduled'?'green':p.draft?'neutral':'blue'}">${statusName(p)}</span></div><h3>${safe(p.title)}</h3><p>${safe(p.caption||'متن محتوا را تکمیل کنید.')}</p><div class="publication-footer"><small>${safe(p.time)}</small><button data-edit-post="${i}" aria-label="ویرایش ${safe(p.title)}">${icon('arrow')}</button></div>${p.reviewNote?`<small class="reviewer-note">یادداشت: ${safe(p.reviewNote)}</small>`:''}</article>`).join('')||'<section class="surface empty"><h3>محتوایی در این وضعیت نیست</h3><p>از ساخت محتوا شروع کنید یا فیلتر دیگری انتخاب کنید.</p></section>'}</div>`}
function contextPanel(){const c=messagesState[selectedInbox],related=orders.filter(o=>o.name===c.name);return `<div class="customer-context"><div class="surface-head"><h3>پرونده مخاطب</h3><button class="text-link" data-close-context>بستن</button></div><span class="person-avatar large avatar-${selectedInbox}">${c.name[0]}</span><b>${c.name}</b><small>${socialNames[c.network]} · ${c.state==='human'?'ارجاع به تیم':c.state==='done'?'بسته‌شده':'گفتگوی باز'}</small><label>مسئول پیگیری</label><select id="context-assignee"><option value="manager" ${c.owner==='manager'?'selected':''}>مدیر فضای کار</option><option value="support" ${c.owner==='support'?'selected':''}>تیم پشتیبانی</option><option value="sales" ${c.owner==='sales'?'selected':''}>تیم فروش</option></select><label>برچسب‌ها</label><div class="customer-tags">${(c.tags||[c.tag]).map(t=>`<span class="tag blue">${safe(t)}</span>`).join('')}</div><form id="tag-form"><input name="tag" placeholder="برچسب تازه" maxlength="25" required aria-label="برچسب تازه"><button class="btn">+</button></form><label>سفارش‌های مرتبط</label>${related.map(o=>`<button class="customer-order" data-order="${orders.indexOf(o)}"><b>#${fa(o.id)} · ${o.product}</b><small>${o.state} · ${o.value} تومان</small></button>`).join('')||'<small>سفارشی ثبت نشده است.</small>'}<label>یادداشت داخلی</label><form id="note-form"><textarea name="note" placeholder="این یادداشت برای تیم است…" required></textarea><button class="btn">ثبت یادداشت</button></form><div class="internal-notes">${(c.notes||[]).map(n=>`<div><b>${roleNames[n.role]||'مدیر'}</b><p>${safe(n.text)}</p></div>`).join('')}</div><div class="handoff-info">${icon('spark')}<p>${c.state==='human'?'پاسخ‌گویی به تیم ارجاع شده است. دستیار فقط پیشنهاد می‌دهد.':'پاسخ پیشنهادی قبل از ثبت، توسط شما قابل بازبینی است.'}</p></div><button class="btn" data-handoff>${c.state==='human'?'بازگشت به صف مدیر':'ارجاع گفتگو به تیم'}</button></div>`}
function enrichInbox(){const aside=main.querySelector('.customer-info');aside.innerHTML=contextPanel();aside.classList.toggle('context-visible',mobileDetail);main.querySelector('.conversation-top').insertAdjacentHTML('beforeend','<button class="btn mobile-context-button" data-show-context>پرونده</button>');main.querySelector('.draft-assistance').insertAdjacentHTML('beforeend',`<div class="suggestion-source">مبنای پیشنهاد: ${safe(messagesState[selectedInbox].subject)} · پاسخ آماده برای بازبینی</div><button class="text-link" data-conversation-content>تبدیل سؤال به ایده محتوا ←</button>`)}
function growthV4(){const c=messagesState[selectedInbox];return titleV3('پیشنهادهای قابل اجرا','هر پیشنهاد با یک دلیل، منبع و قدم بعدی همراه است.',button('همراه هشتیوا','data-agent="context"',false,'spark'))+`<div class="actionable-ideas"><section class="surface"><span class="tag blue">از صندوق گفتگو</span><h3>پاسخ به «${safe(c.subject)}» را به یک پست تبدیل کنید.</h3><p>این موضوع در گفتگوی نمونهٔ ${c.name} مطرح شده؛ می‌تواند نقطه شروع محتوای آموزشی باشد.</p><div class="evidence-line">${icon('inbox')} منبع: گفتگوی ${c.name} · ${socialNames[c.network]}</div><div class="opportunity-action"><button class="btn primary" data-conversation-content>ساخت پیش‌نویس</button><button class="text-link" data-page="inbox">بررسی منبع ←</button></div></section><section class="surface"><span class="tag neutral">از اطلاعات برند</span><h3>شرایط ارسال را شفاف‌تر توضیح دهید.</h3><p>${safe(knowledge.find(k=>k.title.includes('ارسال'))?.text||'ابتدا شرایط ارسال برندتان را در منابع دانش ثبت کنید.')}</p><div class="evidence-line">${icon('book')} منبع: پایگاه دانش برند</div><div class="opportunity-action"><button class="btn" data-knowledge-content>ساخت پیش‌نویس</button><button class="text-link" data-page="knowledge">بازبینی منبع ←</button></div></section></div><div class="section-label"><h2>آزمایش‌های پیشنهادی</h2><small>پیشنهادهای آماده؛ بدون تحلیل مدل زنده</small></div>${growthV3().slice(growthV3().indexOf('<div class="growth-grid">'))}`}
function onboardingPage(){const profile=JSON.parse(localStorage.getItem('ht-onboarding-profile')||'{}');const steps=[['حساب‌ها','channels','یک حساب نمونه برای شبکه دلخواه اضافه کنید.'],['هویت برند','settings','مخاطب و لحن برند را مشخص کنید.'],['آموزش دستیار','knowledge','یک منبع اطلاعات معتبر وارد کنید.'],['اولین محتوا','studio','اولین پیش‌نویس را برای بازبینی آماده کنید.']];return titleV3('راه‌اندازی فضای کار','چهار قدم برای آماده‌کردن هشتیوا؛ پیشرفت شما در مرورگر حفظ می‌شود.')+`<div class="setup-progress"><div><b>${fa(setupDone.length)} از ۴ قدم تکمیل شده</b><small>می‌توانید هر زمان به این صفحه برگردید.</small></div><div class="progress-track"><i style="width:${setupDone.length*25}%"></i></div></div><div class="setup-grid">${steps.map(([t,p,desc],i)=>`<section class="surface setup-step"><span class="setup-number ${setupDone.includes(i)?'done':''}">${setupDone.includes(i)?'✓':fa(i+1)}</span><h3>${t}</h3><p>${desc}</p><button class="btn" data-page="${p}">باز کردن بخش ←</button><label class="policy-check"><input type="checkbox" data-setup-step="${i}" ${setupDone.includes(i)?'checked':''}>این مرحله را انجام داده‌ام</label></section>`).join('')}</div><section class="surface setup-profile"><h3>هدف اصلی فضای کار</h3><form id="setup-profile"><label>نام برند</label><input name="brand" required value="${safe(profile.brand||'استودیو هشتیوا')}"><label>تمرکز شما</label><select name="goal">${['انتشار منظم محتوا','پاسخ‌گویی سریع‌تر','فروش و پیگیری سفارش'].map(t=>`<option ${profile.goal===t?'selected':''}>${t}</option>`).join('')}</select><p><button class="btn primary">ذخیره هدف</button></p></form></section>`}
function channelsV4(){return titleV3('حساب‌های اجتماعی','چند حساب، وضعیت مشخص و قابلیت‌های متناسب با هر شبکه.',button('افزودن حساب نمونه','data-add-account',true,'plus'))+`<div class="channels-grid">${accounts.map(a=>{const state=channelState[a.id]||'sample';return `<section class="card channel-card"><div class="card-title">${social(a.network)}<span class="tag ${state==='disconnected'?'amber':state==='loading'?'neutral':'blue'}">${state==='disconnected'?'قطع‌شده · شبیه‌سازی':state==='loading'?'در حال بررسی':'حساب نمونه'}</span></div><h3 dir="auto">${safe(a.name)}</h3><p>${socialNames[a.network]}</p><div class="channel-capability"><small>قالب‌های مورد استفاده در پیش‌نمایش</small><b>${capability[a.network]}</b></div>${state==='disconnected'?'<p class="channel-error">اتصال شبیه‌سازی‌شده قطع است. برای تمرین بازیابی، بررسی مجدد را بزنید.</p>':''}<div class="channel-actions"><button class="btn" data-retry-channel="${safe(a.id)}">${state==='disconnected'?'بررسی مجدد':'بررسی وضعیت'}</button><button class="text-link" data-disconnect-channel="${safe(a.id)}">شبیه‌سازی قطع اتصال</button></div></section>`}).join('')||'<section class="surface empty"><h3>هنوز حسابی ندارید</h3><button class="btn primary" data-add-account>افزودن حساب نمونه</button></section>'}</div><section class="surface available-networks"><h3>افزودن شبکه دیگر</h3><div>${Object.entries(socialNames).map(([n,t])=>`<button class="network-pill" data-add-network="${n}">${social(n)}${t} +</button>`).join('')}</div><small>قابلیت‌های بالا مربوط به طراحی این نسخه‌اند؛ اتصال رسمی و محدودیت‌های واقعی هر شبکه باید هنگام پیاده‌سازی سرویس بررسی شوند.</small></section>`}
function reportsV4(){const open=messagesState.filter(m=>m.state!=='done').length,replyCount=messagesState.reduce((n,m)=>n+m.replies.length,0);const data=insightRange==='week'?[[12400,860,42],[8700,420,28],[5900,310,19]]:[[38200,2100,110],[26400,1240,81],[17800,890,53]];return titleV3('گزارش و تصمیم بعدی','شاخص‌های محتوایی نمونه و وضعیت واقعیِ کارهای ثبت‌شده در این مرورگر.',`<div class="filter-tabs"><button class="${insightRange==='week'?'selected':''}" data-report-range="week">۷ روز</button><button class="${insightRange==='month'?'selected':''}" data-report-range="month">۳۰ روز</button></div>`)+`<div class="overview-metrics">${[['گفتگوی باز',fa(open)],['پاسخ ثبت‌شده',fa(replyCount)],['نیازمند تأیید',fa(posts.filter(p=>p.workflow==='review').length)],['محتوای برنامه‌ریزی‌شده',fa(posts.filter(p=>p.workflow==='scheduled').length)]].map(([t,v])=>`<div class="overview-metric"><div><span>${t}</span><b>${v}</b><small>بر اساس فعالیت محلی شما</small></div></div>`).join('')}</div><section class="surface table-surface">${surfaceHead('کدام محتوا گفتگو ایجاد کرده؟','داده‌های ثابتِ نمونه برای نمایش گزارش')}<div class="table-wrap"><table><thead><tr><th>محتوا</th><th>دسترسی</th><th>ذخیره و اشتراک</th><th>شروع گفتگو</th><th>گفتگو / دسترسی</th></tr></thead><tbody>${['راهنمای انتخاب هدیه','پشت صحنه بسته‌بندی','پاسخ به سؤال‌های ارسال'].map((t,i)=>`<tr><td>${t}</td><td>${fa(data[i][0])}</td><td>${fa(data[i][1])}</td><td>${fa(data[i][2])}</td><td>${(data[i][2]/data[i][0]*100).toLocaleString('fa-IR',{maximumFractionDigits:2})}٪</td></tr>`).join('')}</tbody></table></div></section><div class="decision-grid"><section class="surface"><span class="tag ${open?'amber':'green'}">گفتگو</span><h3>${open?fa(open)+' گفتگو هنوز باز است':'همه گفتگوها بسته شده‌اند'}</h3><p>${open?'پاسخ و مسئول پیگیری را مشخص کنید تا گفتگوها بدون اقدام باقی نمانند.':'پیش از شروع کمپین بعدی، یادداشت‌های گفتگوها را مرور کنید.'}</p><button class="btn" data-page="inbox">بررسی صندوق گفتگو ←</button></section><section class="surface"><span class="tag blue">محتوا</span><h3>آزمایش بعدی: پاسخ روشن به یک سؤال</h3><p>یک موضوع از گفتگوهای مشتریان انتخاب کنید و تعداد شروع گفتگو نسبت به دسترسی را بسنجید.</p><button class="btn" data-page="growth">انتخاب پیشنهاد رشد ←</button></section></div><p class="connection-note">نسبت بالا، شروع گفتگو تقسیم بر دسترسی است؛ به معنی فروش یا نرخ تبدیل خرید نیست. داده واقعی شبکه‌های اجتماعی دریافت نمی‌شود.</p>`}
function teamPage(){return titleV3('تیم و تاریخچه فعالیت','نقش‌ها را در پیش‌نمایش امتحان کنید و تغییرات محتوا را دنبال کنید.',button('عضو نمونه جدید','data-add-member',true,'plus'))+`<div class="role-simulator"><div><b>نقش فعلی شما در پیش‌نمایش</b><small>این انتخاب برای بررسی جریان محصول است و کنترل دسترسی واقعی محسوب نمی‌شود.</small></div><select id="demo-role">${Object.entries(roleNames).map(([r,n])=>`<option value="${r}" ${role===r?'selected':''}>${n}</option>`).join('')}</select></div><section class="surface table-surface"><div class="table-wrap"><table><thead><tr><th>عضو</th><th>نقش</th><th>دسترسی نمایشی</th></tr></thead><tbody>${members.map(m=>`<tr><td>${safe(m.name)}</td><td>${roleNames[m.role]}</td><td>${m.role==='writer'?'ساخت پیش‌نویس و ارسال برای تأیید':m.role==='reviewer'?'بازبینی و تأیید محتوا':'مدیریت محتوا و تنظیمات'}</td></tr>`).join('')}</tbody></table></div></section><section class="surface audit-surface">${surfaceHead('تاریخچه تغییرات','فعالیت‌های ثبت‌شده در همین مرورگر')}${audit.length?audit.slice(0,15).map(a=>`<div class="audit-row"><span>${icon('clock')}</span><div><b>${safe(a.text)}</b><small>${roleNames[a.role]} · ${new Intl.DateTimeFormat('fa-IR',{dateStyle:'short',timeStyle:'short'}).format(new Date(a.time))}</small></div></div>`).join(''):'<p class="muted">با ذخیره محتوا یا تغییر وضعیت گفتگو، اولین فعالیت اینجا ثبت می‌شود.</p>'}</section>`}
const productBaseRender=render;Object.assign(titles,{onboarding:'شروع کار',team:'تیم و فعالیت‌ها'});pages.push(['onboarding','شروع کار','home'],['team','تیم و فعالیت‌ها','users']);const productNav=navV3;navV3=function(){productNav();nav.insertAdjacentHTML('beforeend',`<div class="nav-group-label">فضای کار</div>${[['onboarding','شروع کار','check'],['team','تیم و فعالیت‌ها','users']].map(([p,t,i])=>`<button class="nav-item ${current===p?'active':''}" data-page="${p}">${icon(i)}<span>${t}</span></button>`).join('')}`)};
render=function(page='dashboard'){productBaseRender(page);if(page==='studio')main.innerHTML=studioV4();if(page==='inbox')enrichInbox();if(page==='channels')main.innerHTML=channelsV4();if(page==='growth')main.innerHTML=growthV4();if(page==='analytics')main.innerHTML=reportsV4();if(page==='onboarding')main.innerHTML=onboardingPage();if(page==='team')main.innerHTML=teamPage();if(page==='dashboard'&&setupDone.length<4)main.insertAdjacentHTML('afterbegin',`<div class="onboarding-banner"><div><b>فضای کاری‌تان را آماده کنید</b><small>${fa(setupDone.length)} از ۴ قدم انجام شده است.</small></div><button class="btn" data-page="onboarding">ادامه راه‌اندازی ←</button></div>`);};
// Composer actions are intercepted once, before legacy dialog handlers.
document.addEventListener('click',e=>{const t=e.target.closest('[data-action="post"],[data-edit-post],[data-use-idea]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.hasAttribute('data-edit-post'))openComposer(+t.dataset.editPost);else if(t.hasAttribute('data-use-idea')){const idea=growthIdeas[+t.dataset.useIdea];openComposer(-1,{title:idea[1],caption:idea[2]})}else openComposer(-1,{due:t.dataset.calendarDate?t.dataset.calendarDate+'T18:00':''})},true);
document.addEventListener('click',e=>{let t=e.target.closest('[data-composer-step]');if(t){if(+t.dataset.composerStep>0&&(!composer.networks.length||!composer.title.trim()))return composerError('عنوان و حداقل یک شبکه را انتخاب کنید.');composerStep=+t.dataset.composerStep;showComposer()}if(e.target.closest('[data-composer-next]')){if(!composer.title.trim()||!composer.networks.length)return composerError('عنوان و حداقل یک شبکه را انتخاب کنید.');composerStep++;showComposer()}if(e.target.closest('[data-composer-back]')){composerStep--;showComposer()}t=e.target.closest('[data-preview-network]');if(t){composerPreview=t.dataset.previewNetwork;showComposer()}t=e.target.closest('[data-save-composer]');if(t)saveComposer(t.dataset.saveComposer);if(e.target.closest('[data-caption-suggestion]')){composer.caption=`${composer.title||'یک انتخاب بهتر'}\nگاهی یک نکته کوچک، انتخاب را ساده‌تر می‌کند. در این محتوا نکته‌های کاربردی را مرور می‌کنیم.\nشما چه تجربه‌ای دارید؟ در دیدگاه‌ها برایمان بنویسید.`;showComposer();toast('متن آماده پیشنهاد شد؛ پیش از استفاده ویرایش کنید.')}if(e.target.closest('[data-remove-media]')){composer.media='';showComposer()}if(e.target.closest('[data-show-context]')){mobileDetail=true;main.querySelector('.customer-info').classList.add('context-visible')}if(e.target.closest('[data-close-context]')){mobileDetail=false;main.querySelector('.customer-info').classList.remove('context-visible')}if(e.target.closest('[data-handoff]')){const m=messagesState[selectedInbox];m.state=m.state==='human'?'open':'human';m.owner=m.state==='human'?'support':'manager';saveV3();logAction('تغییر مسئول پیگیری: '+m.name);render('inbox')}if(e.target.closest('[data-conversation-content]')){const m=messagesState[selectedInbox];openComposer(-1,{title:'پاسخ به '+m.subject,caption:'سؤال شما: '+m.text+'\n\nپاسخ را با اطلاعات معتبر برند تکمیل کنید.',kind:'متن',origin:'گفتگوی '+m.name})}if(e.target.closest('[data-knowledge-content]')){const k=knowledge.find(k=>k.title.includes('ارسال'));if(!k){location.hash='knowledge';return}openComposer(-1,{title:k.title,caption:k.text,kind:'متن',origin:'منبع دانش: '+k.title})}t=e.target.closest('[data-disconnect-channel]');if(t){channelState[t.dataset.disconnectChannel]='disconnected';persistAccounts();render('channels')}t=e.target.closest('[data-retry-channel]');if(t){const id=t.dataset.retryChannel;channelState[id]='loading';render('channels');setTimeout(()=>{channelState[id]='sample';persistAccounts();if(current==='channels')render('channels');toast('بررسی نمایشی کامل شد؛ اتصال خارجی انجام نشد.')},700)}t=e.target.closest('[data-report-range]');if(t){insightRange=t.dataset.reportRange;render('analytics')}if(e.target.closest('[data-add-member]'))modal('<h2>عضو نمونه جدید</h2><small>این فرم دعوت‌نامه ارسال نمی‌کند.</small><form id="member-form"><label>نام عضو</label><input name="name" required maxlength="50"><label>نقش</label><select name="role"><option value="writer">نویسنده</option><option value="reviewer">بازبین</option><option value="manager">مدیر</option></select><p><button class="btn primary">افزودن به تیم نمونه</button></p></form>')});
document.addEventListener('input',e=>{if(e.target.matches('[data-cfield]')){composer[e.target.dataset.cfield]=e.target.value;if(e.target.dataset.cfield==='caption'){const count=document.querySelector('#caption-count');if(count)count.textContent=fa(e.target.value.length)+' نویسه'}refreshComposerPreview();if(e.target.dataset.cfield==='due'){document.querySelector('#jalali-preview').textContent=e.target.value?new Intl.DateTimeFormat('fa-IR',{dateStyle:'full',timeStyle:'short'}).format(new Date(e.target.value)):''}}if(e.target.matches('[data-variant]')){composer.captions[e.target.dataset.variant]=e.target.value;refreshComposerPreview()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-cnetwork]')){const n=e.target.dataset.cnetwork;composer.networks=e.target.checked?[...new Set([...composer.networks,n])]:composer.networks.filter(x=>x!==n);if(!composer.networks.includes(composerPreview))composerPreview=composer.networks[0]||'instagram';showComposer()}if(e.target.id==='preview-network-select'){composerPreview=e.target.value;refreshComposerPreview()}if(e.target.id==='composer-image'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1024*1024)return composerError('تصویر PNG، JPG یا WebP با حجم کمتر از ۱ مگابایت انتخاب کنید.');const reader=new FileReader(),uploadSession=composer;reader.onload=()=>{if(composer!==uploadSession||!dialog.open)return;composer.media=reader.result;showComposer()};reader.onerror=()=>composer&&composerError('خواندن تصویر انجام نشد؛ دوباره انتخاب کنید.');reader.readAsDataURL(file)}if(e.target.id==='context-assignee'){const m=messagesState[selectedInbox];m.owner=e.target.value;m.state=e.target.value==='manager'?'open':'human';saveV3();logAction('ارجاع گفتگو: '+m.name);render('inbox')}if(e.target.matches('[data-setup-step]')){const i=+e.target.dataset.setupStep;setupDone=e.target.checked?[...new Set([...setupDone,i])]:setupDone.filter(x=>x!==i);localStorage.setItem('ht-setup',JSON.stringify(setupDone));render('onboarding')}if(e.target.id==='demo-role'){role=e.target.value;localStorage.setItem('ht-role',role);toast('نقش نمایشی به '+roleNames[role]+' تغییر کرد.')}});
document.addEventListener('submit',e=>{const f=new FormData(e.target);if(e.target.id==='note-form'){const text=f.get('note').trim();if(!text)return;const m=messagesState[selectedInbox];(m.notes??=[]).unshift({text,role});saveV3();logAction('یادداشت داخلی برای '+m.name);render('inbox')}if(e.target.id==='tag-form'){const tag=f.get('tag').trim();if(!tag)return;const m=messagesState[selectedInbox];m.tags=[...new Set([...(m.tags||[m.tag]),tag])];saveV3();render('inbox')}if(e.target.id==='setup-profile'){localStorage.setItem('ht-onboarding-profile',JSON.stringify({brand:f.get('brand'),goal:f.get('goal')}));localStorage.setItem('hashtiva-business',f.get('brand'));document.querySelector('.workspace b').textContent=f.get('brand');toast('هدف فضای کار ذخیره شد')}if(e.target.id==='member-form'){members.push({name:f.get('name'),role:f.get('role')});localStorage.setItem('ht-members',JSON.stringify(members));logAction('افزودن عضو نمونه: '+f.get('name'));dialog.close();render('team')}if(['inbox-compose','order-form','knowledge-form','flow-form'].includes(e.target.id))logAction({ 'inbox-compose':'ثبت پاسخ در صندوق گفتگو','order-form':'تغییر وضعیت سفارش','knowledge-form':'ذخیره منبع دانش','flow-form':'ذخیره جریان خودکار'}[e.target.id])});
render(location.hash.slice(1)||'dashboard');
const actionableAgentHeader=updateAgentHeader;updateAgentHeader=function(){actionableAgentHeader();document.querySelector('#agent-prompts').insertAdjacentHTML('beforeend','<button data-agent-draft>ساخت پیش‌نویس قابل ویرایش ←</button>')};
document.addEventListener('click',e=>{if(e.target.closest('[data-agent-draft]')){document.querySelector('#agent-panel').hidden=true;document.querySelector('#agent-launcher').setAttribute('aria-expanded','false');const c=contexts[current]||contexts.studio;openComposer(-1,{title:c[1],caption:c[2],kind:'متن',origin:'پیشنهاد آمادهٔ همراه هشتیوا؛ نیازمند بازبینی'})}});
const workspaceName=localStorage.getItem('hashtiva-business');if(workspaceName)document.querySelector('.workspace b').textContent=workspaceName;updateAgentHeader();
